assert len(P)==20, len(P)
total=0; written=0
for cid,(text,basis,trig) in P.items():
    obj={"case_id":cid,"prediction_text":text,"basis":basis,"confidence":0.0,"trigger":trig}
    # confidence embedded per case below
    conf={"YM-019":0.62,"YM-020":0.70,"YM-022":0.60,"YM-023":0.65,"YM-024":0.55,"YM-025":0.68,"YM-027":0.58,"YM-028":0.60,"YM-029":0.62,"YM-030":0.57,"YM-032":0.50,"YM-033":0.64,"YM-034":0.60,"YM-035":0.62,"YM-037":0.66,"YM-038":0.60,"YM-039":0.65,"YM-040":0.63,"YM-042":0.52,"YM-043":0.72}[cid]
    obj["confidence"]=conf
    path=os.path.join(BASE,cid+".json")
    with open(path,"w",encoding="utf-8") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
    # self verify
    with open(path,encoding="utf-8") as f:
        back=json.load(f)
    assert back["case_id"]==cid and set(back.keys())=={"case_id","prediction_text","basis","confidence","trigger"}
    assert set(back["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
    total+=os.path.getsize(path); written+=1
print("written",written,"total_bytes",total)
print("changed",sum(1 for v in P.values() if v[2]["changed_main"]),"reserve",sum(1 for v in P.values() if v[2]["reserve_used"]),"disputed",sum(1 for v in P.values() if v[2]["disputed"]))
